def encode_shift(s: str):
    """
    Returns a new string with every character shifted by 5 in the alphabet shift value.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    Transforms a shifted version of an encrypted string back into the original form.
    """
    return encode_shift(s)
