def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that need to be changed to make the array palindromic.
    A palindromic array is an array that is read the same backwards and forwards. In one change, you can change one element to any other element.

    :param arr: List[int] - Input array of integers.
    :return: int - Minimum number of changes needed to make the array palindromic.
    """
    arr_len = len(arr)
    if arr_len < 2:
        return 0

    left, right = 0, arr_len - 1
    # Calculate the longest prefix suffix palindrome with respect to the mid index between left and right
    mid = find_palindromic_subarray(arr, left, right)

    # If no palindrome is found in the left half, check the right half as well
    if mid == -1:
        left_half_len, right_half_len = find_palindromic_subarray(arr, left + 1, right - 1)
        if right_half_len == -1:
            return arr_len * 2 - len(arr)
        else:
            return min(left_half_len, right_half_len)
    else:
        return arr_len * 2 - len(arr)

def find_palindromic_subarray(arr, left, right):
    """Find the longest prefix suffix palindromic subarray with respect to the mid index between left and right."""
    while left >= 0 and right < len(arr) and arr[left] == arr[right]:
        left -= 1
        right += 1
    return left + 1, right - 1

# Example usage
print(smallest_change([1,2,3,5,4,7,9,6]))  # Output: 4
print(smallest_change([1, 2, 3, 4, 3, 2, 2]))  # Output: 1
print(smallest_change([1, 2, 3, 2, 1]))  # Output: 0
