def total_match(lst1, lst2):
    if len(lst1) != len(lst2):
        return lst1

    total_chars_less_than_other = sum(map(lambda x, y: x + y, lst1, lst2))

    if total_chars_less_than_other == 0:
        return lst1

    return lst1 if total_chars_less_than_other < len(lst2) else lst2
