def iscube(a):
    '''
    Write a function that takes an integer a and returns True 
    if this integer is a cube of some integer number.
    Note: you may assume the input is always valid.
    Examples:
    iscube(1) ==> True
    iscube(2) ==> False
    iscube(-1) ==> True
    iscube(64) ==> True
    iscube(0) ==> True
    iscube(180) ==> False
    '''
    import math
    if a == 0: 
        return(True)
    elif a < 0:
        return(False)
    else:
        root = math.sqrt(a)
        if root.is_integer():
            return root == int(root)
        else:
            return False

