def numerical_letter_grade(grades):
    letter_grades = ["A+", "A-", "B+", "B-", "C+", "C-", "D+", "D-", "E"]
    letter_grades_index = [4.0, 3.7, 3.3, 3.0, 2.7]
    result_grades = []

    for grade, gpa in zip(grades, letter_grades_index):
        for i, grade_grading in enumerate(letter_grades):
            if 0.0 < gpa <= grade and 'A' <= grade_grading <= 'B':
                result_grades.append(grade_grading)
