def get_closest_vowel(word):
    # Create a list of vowels for quick lookup
    vowels = 'aeiouAEIOU'

    # Convert the word to lowercase for case insensitivity
    word = word.lower()

    # Check for vowels in the word from the right
    found = False
    for i in range(len(word) - 2, -1, -1):
        if word[i] in vowels:
            # Find the next non-vowel character to the left of the current vowel
            found = True
            for j in range(i+1, len(word)):
                if word[j] not in vowels and not word[j].isalpha():
                    found = False
                    break
            if found:
                return word[i+1]  # Return the closest vowel found

    # Check for vowels in the word from the left
    for i in range(len(word) - 1, -1, -1):
        if word[i] in vowels:
            found = True
            for j in range(i-1, -1, -1):
                if word[j] not in vowels and not word[j].isalpha():
                    found = False
                    break
            if found:
                return word[i]  # Return the closest vowel found

    # If no vowel is found, return an empty string
    return ""

